HARD_CAP_SECONDS: Final = 900
CELERY_SOFT_LIMIT_SECONDS: Final = 100  # worker/app.py: alerts.evaluate soft limit
HOURLY_DAYS_ENV: Final = "CFI_P51_SEED_HOURLY_DAYS"

#: The marker is a comment on the dedicated disposable database ``p51_scratch_test`` only.
EXPECTED_MARKER: Final = "P51_DISPOSABLE"
#: Every non-template database the server may hold: the maintenance database, the application's
#: scratch database and the disposable test database. Anything else means the server is not the
#: dedicated scratch instance the procedure describes, and nothing is changed.
APPROVED_DATABASES: Final = frozenset({"postgres", EXPECTED_DATABASE, EXPECTED_TEST_DATABASE})
REQUIRED_DATABASES: Final = frozenset({EXPECTED_DATABASE, EXPECTED_TEST_DATABASE})

#: Historical regime/similarity evidence required before a timing is accepted.
MIN_HISTORICAL_GATHERS: Final = 100  # a current-only snapshot would show 2-4 per read name
COVERAGE_OFFSETS_DAYS: Final = (0, 30, 100, 200, 365, 540, 700)
MIN_OK_METRICS_ANYWHERE: Final = 9  # of 13; the derivatives inputs are provider-depth limited
EXPECTED_STAGES: Final = (
    "build_snapshot",
    "persist_snapshot",
    "evaluate_rules",
    "process_candidates",
    "auto_resolve",
    "investment_block",
)
#: Fields of the ``analyst_snapshot_pit_memo`` event copied into each run's report block. The
#: ``window_*`` counters say how many revision-window requests were served from a window, how many
#: SQL reads filled or extended one, and how many used the existing SQL instead.
PIT_MEMO_REPORT_KEYS: Final = (
    "hits",
    "misses",
    "uncached",
    "hits_by_name",
    "misses_by_name",
    "window_hits",
    "window_loads",
    "window_fallbacks",
)
READ_NAMES: Final = (
    "institutional.score",
    "whales.score",
    "retail.overview",
    "liquidity.overview",
    "derivatives.asset",
    "macro.overview_score",
    "market_structure.overview",
)

_GATE = evaluate_gate(os.environ)
requires_disposable_database = pytest.mark.skipif(
    not _GATE.ok,
    reason=(
        "Phase 51 database gate not satisfied (failed checks: "
        f"{', '.join(_GATE.failures) or 'none'}); set the target only after it has been "
        "independently verified as disposable"
    ),
)


# ---------------------------------------------------------------------------------------------
# Target verification (pure decision + one read-only fact-gathering function)
# ---------------------------------------------------------------------------------------------


@dataclass(frozen=True, slots=True)
class TargetFacts:
    current_database: str
    marker: str | None
    databases: frozenset[str]  # every non-template database on the server
    in_recovery: bool


def target_failures(facts: TargetFacts) -> tuple[str, ...]:
    """Failure codes for a target that is not provably the disposable database (empty = OK)."""
    failures: list[str] = []
    if facts.current_database != EXPECTED_TEST_DATABASE:
        failures.append("connected_database_not_expected")
    if facts.marker != EXPECTED_MARKER:
        failures.append("disposable_marker_missing_or_wrong")
    unapproved = sorted(facts.databases - APPROVED_DATABASES)
    if unapproved:
        failures.append("unapproved_databases_present:" + ",".join(unapproved))
    missing = sorted(REQUIRED_DATABASES - facts.databases)
    if missing:
        failures.append("required_databases_missing:" + ",".join(missing))
    if facts.in_recovery:
        failures.append("server_is_a_replica")
    return tuple(failures)


def read_target_facts(url: URL) -> TargetFacts:
    """Read-only: connect to the candidate database and collect the facts to be judged."""
    dsn = url.set(drivername="postgresql").render_as_string(hide_password=False)
    with psycopg.connect(dsn, autocommit=True, connect_timeout=10) as conn:
        current = conn.execute("SELECT current_database()").fetchone()
        marker = conn.execute(
            "SELECT shobj_description(oid, 'pg_database') FROM pg_database "
            "WHERE datname = current_database()"
        ).fetchone()
        names = conn.execute("SELECT datname FROM pg_database WHERE NOT datistemplate").fetchall()
        recovery = conn.execute("SELECT pg_is_in_recovery()").fetchone()
    assert current is not None
    assert marker is not None
    assert recovery is not None
    return TargetFacts(
        current_database=str(current[0]),
        marker=None if marker[0] is None else str(marker[0]),
        databases=frozenset(str(r[0]) for r in names),
        in_recovery=bool(recovery[0]),
    )


@pytest.fixture(scope="module")
def p51_target_url() -> Iterator[str]:
    """URL of ``p51_scratch_test`` once - and only once - every check has passed. Replaces the
    stock ``test_database_url`` fixture (which drops and recreates the database); this module
    must never request that fixture, ``db`` or ``test_settings``."""
    gate = evaluate_gate(os.environ)
    if not gate.ok:  # normally unreachable: the skip mark stops the module first
        pytest.fail("Phase 51 gate failed: " + ", ".join(gate.failures))
    target = make_url(os.environ[DATABASE_URL_ENV]).set(database=EXPECTED_TEST_DATABASE)
    try:
        facts = read_target_facts(target)
    except psycopg.Error:
        pytest.fail(
            f"cannot read the target {EXPECTED_TEST_DATABASE!r} (does it exist, and may this role "
            "connect to it?); nothing was changed"
        )
    failures = target_failures(facts)
    if failures:
        pytest.fail(
            "Phase 51 target rejected, nothing was changed: "
            + "; ".join(failures)
            + f". Prerequisite: COMMENT ON DATABASE {EXPECTED_TEST_DATABASE} IS "
            f"'{EXPECTED_MARKER}' and a server holding only {sorted(APPROVED_DATABASES)}."
        )
    url = target.render_as_string(hide_password=False)
    with isolated_database_env(url):
        command.upgrade(alembic_config(), "head")  # additive; first statement that changes data
        yield url


async def truncate_verified(engine: AsyncEngine) -> None:
    """Empty the data tables of the disposable database. The connected database and its marker are
    re-read in the very transaction that truncates, so a mis-pointed engine fails before any
    statement that changes data. Never drops or recreates anything."""
    async with engine.begin() as conn:
        name = (await conn.execute(text("SELECT current_database()"))).scalar_one()
        marker = (
            await conn.execute(
                text(
                    "SELECT shobj_description(oid, 'pg_database') FROM pg_database "
                    "WHERE datname = current_database()"
                )
            )
        ).scalar_one()
        if name != EXPECTED_TEST_DATABASE or marker != EXPECTED_MARKER:
            raise RuntimeError("refusing to truncate: not the marked disposable database")
        await conn.execute(text(f"TRUNCATE {', '.join(DATA_TABLES)} RESTART IDENTITY CASCADE"))


# ---------------------------------------------------------------------------------------------
# Tests that need no database
# ---------------------------------------------------------------------------------------------

_GOOD = TargetFacts(
    current_database=EXPECTED_TEST_DATABASE,
    marker=EXPECTED_MARKER,
    databases=APPROVED_DATABASES,
    in_recovery=False,
)


def test_target_is_accepted_only_when_every_fact_matches() -> None:
    assert target_failures(_GOOD) == ()
    cases = {
        "wrong database": TargetFacts("p51_scratch", EXPECTED_MARKER, APPROVED_DATABASES, False),
        "no marker": TargetFacts(EXPECTED_TEST_DATABASE, None, APPROVED_DATABASES, False),
        "marker on wrong text": TargetFacts(
            EXPECTED_TEST_DATABASE, "p51", APPROVED_DATABASES, False
        ),
        "extra database": TargetFacts(
            EXPECTED_TEST_DATABASE, EXPECTED_MARKER, APPROVED_DATABASES | {"cfi"}, False
        ),
        "scratch database absent": TargetFacts(
            EXPECTED_TEST_DATABASE,
            EXPECTED_MARKER,
            frozenset({"postgres", EXPECTED_TEST_DATABASE}),
            False,
        ),
        "replica": TargetFacts(EXPECTED_TEST_DATABASE, EXPECTED_MARKER, APPROVED_DATABASES, True),
    }
    for label, facts in cases.items():
        assert target_failures(facts), label


def test_seed_is_deterministic_without_a_database() -> None:
    """Two independent generations of the whole history are byte-identical (fingerprint and
    counts); a different hourly depth is a different, but equally stable, dataset."""

    async def both() -> tuple[seed.SeedSummary, seed.SeedSummary, seed.SeedSummary]:
        return (
            await seed.dry_run(),
            await seed.dry_run(),
            await seed.dry_run(hourly_days=seed.MAX_HOURLY_DAYS),
        )

    first, second, deep = asyncio.run(both())
    assert first.fingerprint == second.fingerprint
    assert first.table_counts == second.table_counts
    assert deep.fingerprint != first.fingerprint
    assert deep.table_counts["obs.observation"] > first.table_counts["obs.observation"]
    assert first.analysis_days == 730


# ---------------------------------------------------------------------------------------------
# The benchmark
# ---------------------------------------------------------------------------------------------


def _hourly_days() -> int:
    raw = os.environ.get(HOURLY_DAYS_ENV)
    return seed.DEFAULT_HOURLY_DAYS if not raw else int(raw)


async def _regime_inputs(engine: AsyncEngine) -> dict[str, dict[str, Any]]:
    """Status of every regime metric at today and at historical dates (via the real gatherer)."""
    adapters = Adapters(engine)
    out: dict[str, dict[str, Any]] = {}
    for offset in COVERAGE_OFFSETS_DAYS:
        moment = seed.ANCHOR - timedelta(days=offset)
        snap = await gather_snapshot(adapters, asset="BTC", as_of=moment, knowledge_time=moment)
        statuses = {name: reading.status for name, reading in snap.metrics.items()}
        out[f"-{offset}d"] = {
            "ok": sum(1 for s in statuses.values() if s == "ok"),
            "total": len(statuses),
            "not_ok": sorted(n for n, s in statuses.items() if s != "ok"),
        }
    return out


@dataclass(slots=True)
class Run:
    wall_seconds: float
    result: EvaluationResult
    events: list[dict[str, Any]]

    def by_event(self, name: str) -> list[dict[str, Any]]:
        return [e for e in self.events if e.get("event") == name]

    @property
    def memo(self) -> dict[str, Any]:
        [memo] = self.by_event("analyst_snapshot_pit_memo")
        return memo

    @property
    def gathers_by_name(self) -> dict[str, int]:
        memo = self.memo
        return {
            n: int(memo["hits_by_name"].get(n, 0)) + int(memo["misses_by_name"].get(n, 0))
            for n in READ_NAMES
        }


def _last_event(events: list[Any]) -> str | None:
    """Name of the most recent completed stage/tool timing event (what evaluate last finished)."""
    for event in reversed(events):
        if event.get("event") in ("alert_evaluate_stage_timing", "analyst_snapshot_tool_timing"):
            return f"{event['event']}:{event.get('stage') or event.get('tool_id')}"
    return None


async def _heartbeat(progress: Progress, label: str, started: float, events: list[Any]) -> None:
    while True:
        await asyncio.sleep(HEARTBEAT_SECONDS)
        progress.heartbeat(label, time.perf_counter() - started, _last_event(events))


async def _evaluate(service: AlertService, progress: Progress, label: str) -> Run:
    with structlog.testing.capture_logs() as events:
        started = time.perf_counter()
        beat = asyncio.create_task(_heartbeat(progress, label, started, events))
        try:
            result = await asyncio.wait_for(
                service.evaluate(as_of=seed.ANCHOR, knowledge_time=seed.ANCHOR, now=seed.ANCHOR),
                timeout=HARD_CAP_SECONDS,
            )
        except TimeoutError:
            elapsed = time.perf_counter() - started
            progress.timed_out = label
            pytest.fail(
                f"TIMEOUT: the real AlertService.evaluate did not finish within the "
                f"{HARD_CAP_SECONDS} s hard cap (stopped after {elapsed:.0f} s). This is a "
                "timeout, not a benchmark result; no duration is reported as a measurement. "
                f"Last completed event: {_last_event(events)}."
            )
        finally:
            beat.cancel()
            # Collects the heartbeat's own cancellation; a cancellation of *this* task still raises.
            await asyncio.gather(beat, return_exceptions=True)
    return Run(time.perf_counter() - started, result, [dict(e) for e in events])


@dataclass
class _Lifecycle:
    report: Path | None = None  # set by the benchmark once the durable report is written


async def _release(engine: AsyncEngine, progress: Progress, *, propagate: bool) -> None:
    """Required cleanup, in this order: dispose the engine, then stop the diagnostics (which stay
    alive during the disposal, so a hang there is still dumped). A cleanup error never replaces
    the benchmark's own exception: it propagates only when the benchmark itself succeeded."""
    if not propagate:
        progress.body_aborted()  # no-op unless a stage has not already recorded the failure
    try:
        await engine.dispose()
    except Exception as exc:
        progress.cleanup_failed("engine_dispose", exc)
        if propagate:
            raise
    finally:
        progress.close()  # never raises; a failure is recorded and blocks "completed"


@contextlib.asynccontextmanager
async def _lifecycle(engine: AsyncEngine, progress: Progress) -> AsyncIterator[_Lifecycle]:
    """Cleanup first, verdict last. ``complete`` runs only after the body succeeded AND the engine
    is disposed AND the diagnostics are closed, so no cleanup step can follow ``completed``."""
    life = _Lifecycle()
    succeeded = False
    try:
        yield life
        succeeded = True
    finally:
        await _release(engine, progress, propagate=succeeded)
    progress.complete(life.report)


def pit_memo_block(run: Run) -> dict[str, Any]:
    return {k: run.memo[k] for k in PIT_MEMO_REPORT_KEYS}


def _stage_ms(run: Run) -> dict[str, float]:
    return {e["stage"]: float(e["elapsed_ms"]) for e in run.by_event("alert_evaluate_stage_timing")}


def _tool_ms(run: Run) -> dict[str, float]:
    return {
        e["tool_id"]: float(e["elapsed_ms"]) for e in run.by_event("analyst_snapshot_tool_timing")
    }


def _require_historical_processing(run: Run) -> dict[str, Any]:
    """Reject the timing unless the historical regime and similarity passes demonstrably ran."""
    stages = {e["stage"]: e["status"] for e in run.by_event("alert_evaluate_stage_timing")}
    assert set(stages) == set(EXPECTED_STAGES), stages
    assert all(status == "ok" for status in stages.values()), stages
    tools = {e["tool_id"]: e["status"] for e in run.by_event("analyst_snapshot_tool_timing")}
    assert len(tools) == 13, tools
    assert set(tools.values()) == {"ok"}, tools
    gathers = run.gathers_by_name
    assert min(gathers.values()) >= MIN_HISTORICAL_GATHERS, gathers
    assert run.result.snapshot is not None
    results = run.result.snapshot.payload()["tool_results"]
    regime = results["get_market_regime"]
    similar = results["find_historical_similar_periods"]
    regime_data = regime.get("data", regime)
    similar_data = similar.get("data", similar)
    assert regime_data["status"] == "ok", regime_data.get("reason")
    assert regime_data["regime_duration_days"] is not None
    assert similar_data["status"] == "ok", similar_data.get("reason")
    assert int(similar_data["candidates_evaluated"]) > 0
    assert len(similar_data["analogues"]) > 0
    return {
        "regime_id": regime_data["regime_id"],
        "regime_duration_days": regime_data["regime_duration_days"],
        "regime_historical_examples": len(regime_data["historical_examples"]),
        "similarity_candidates_evaluated": int(similar_data["candidates_evaluated"]),
        "similarity_analogues": len(similar_data["analogues"]),
        "gathers_by_read": gathers,
    }


@requires_disposable_database
@requires_services
@pytest.mark.integration
async def test_seeded_two_year_evaluate_benchmark(
    p51_target_url: str, tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    hourly_days = _hourly_days()
    progress = Progress(
        progress_dir(),
        {
            "hourly_days": hourly_days,
            "hard_cap_seconds": HARD_CAP_SECONDS,
            "database": EXPECTED_TEST_DATABASE,
        },
    )
    progress.mark(
        f"benchmark started: hourly_days={hourly_days}, evaluation cap {HARD_CAP_SECONDS}s, "
        f"database {EXPECTED_TEST_DATABASE}, checkpoint {progress.path}"
    )
    progress.mark(
        "database safety gates passed (fixture resolved: target verified, schema at head)"
    )
    with progress.stage("engine_setup"):
        settings = isolated_settings(get_settings(), p51_target_url, tmp_path / "raw")
        assert engine_database_name(settings) == EXPECTED_TEST_DATABASE
        engine = create_engine(settings)
    async with _lifecycle(engine, progress) as life:
        progress.start_stack_dumps()  # stopped by _release, after the engine is disposed
        with progress.stage("truncate"):
            await truncate_verified(engine)

        started = time.perf_counter()
        with progress.stage("seed"):
            summary = await seed.seed_database(engine, tmp_path / "raw", hourly_days=hourly_days)
            progress.detail(rows_by_table=summary.table_counts)
        seed_seconds = time.perf_counter() - started
        with progress.stage("seed_verify"):
            assert await seed.stored_counts(engine) == summary.table_counts
            assert (await seed.dry_run(hourly_days)).fingerprint == summary.fingerprint

        with progress.stage("coverage_checks"):
            coverage = await _regime_inputs(engine)
            assert coverage["-0d"]["ok"] == coverage["-0d"]["total"], coverage["-0d"]
            for label, entry in coverage.items():
                assert entry["ok"] >= MIN_OK_METRICS_ANYWHERE, (label, entry)

        with progress.stage("evaluate_1"):
            service = AlertService(engine, settings)
            first = await _evaluate(service, progress, "evaluate_1")
            progress.detail(wall_seconds=round(first.wall_seconds, 2))
        with progress.stage("historical_assertions_1"):
            evidence = _require_historical_processing(first)

        second = None
        if first.wall_seconds < HARD_CAP_SECONDS / 2:
            with progress.stage("evaluate_2"):
                second = await _evaluate(service, progress, "evaluate_2")
                progress.detail(wall_seconds=round(second.wall_seconds, 2))
            with progress.stage("historical_assertions_2"):
                _require_historical_processing(second)
                # The work is deterministic; the durations are measurements and only reported.
                assert second.gathers_by_name == first.gathers_by_name
                assert second.memo["hits"] == first.memo["hits"]
                assert second.memo["misses"] == first.memo["misses"]
        else:
            progress.mark("evaluate_2 skipped: the first evaluation took at least half the cap")

        with progress.stage("environment_metadata"):
            async with engine.connect() as conn:
                server_version = (await conn.execute(text("SHOW server_version"))).scalar_one()
                timescale = (
                    await conn.execute(
                        text("SELECT extversion FROM pg_extension WHERE extname = 'timescaledb'")
                    )
                ).scalar_one_or_none()

        def block(run: Run) -> dict[str, Any]:
            return {
                "wall_clock_seconds": round(run.wall_seconds, 2),
                "within_celery_soft_limit_100s": run.wall_seconds < CELERY_SOFT_LIMIT_SECONDS,
                "stage_ms": _stage_ms(run),
                "tool_ms": _tool_ms(run),
                "pit_memo": pit_memo_block(run),
            }

        with progress.stage("report_build"):
            report = {
                "kind": REPORT_KIND,
                "run_id": progress.run_id,
                "SYNTHETIC": "synthetic data on a disposable database; NOT production performance",
                "seed": {
                    "version": summary.seed_version,
                    "seed": summary.seed,
                    "fingerprint_sha256": summary.fingerprint,
                    "hourly_days": summary.hourly_days,
                    "analysis_days": summary.analysis_days,
                    "daily_days_including_warmup": summary.daily_days,
                    "first_day": summary.first_day.isoformat(),
                    "anchor": summary.anchor.isoformat(),
                    "series": summary.series_count,
                    "rows_by_table": summary.table_counts,
                    "seconds_to_seed": round(seed_seconds, 1),
                },
                "environment": {
                    "postgres": server_version,
                    "timescaledb": timescale,
                    "python": platform.python_version(),
                    "platform": platform.platform(),
                },
                "regime_inputs_by_offset": coverage,
                "historical_processing": evidence,
                "hard_cap_seconds": HARD_CAP_SECONDS,
                "run_1": block(first),
                "run_2": None if second is None else block(second),
            }
            rendered = json.dumps(report, indent=2, sort_keys=True, default=str)
        with progress.stage("report_write"):
            durable_report = progress.write_report(rendered)  # None = not safely on disk
            progress.detail(durable_report_persisted=durable_report is not None)
            (tmp_path / "p51_benchmark_report.json").write_text(rendered)
            with capsys.disabled():
                print("\n===== PHASE 51 SEEDED BENCHMARK (SYNTHETIC) =====\n" + rendered)
                print(f"report file: {tmp_path / 'p51_benchmark_report.json'}")
        life.report = durable_report  # the verdict is issued by _lifecycle, after the cleanup
